import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"什么是运行环境和节点","description":"分清运行环境、实际服务器节点、基础服务、运行引擎和部署，不把开发工作区或多节点等同于正式运行与高可用。","frontmatter":{"title":"什么是运行环境和节点","description":"分清运行环境、实际服务器节点、基础服务、运行引擎和部署，不把开发工作区或多节点等同于正式运行与高可用。","status":"reviewed","kind":"explanation"},"headers":[],"relativePath":"zh/concepts/environments-and-nodes.md","filePath":"zh/核心概念/什么是运行环境和节点.md"}'),n={name:"zh/concepts/environments-and-nodes.md"};function o(h,t,i,l,s,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="什么是运行环境和节点" tabindex="-1">什么是运行环境和节点 <a class="header-anchor" href="#什么是运行环境和节点" aria-label="Permalink to &quot;什么是运行环境和节点&quot;">​</a></h1><p>先记住：<strong>运行环境是安排应用运行的范围，节点是实际承担工作的服务器。</strong> 环境里有名字和配置，不代表服务器、服务和工程都已经准备完毕。</p><h2 id="运行环境-把一组运行安排放在一起" tabindex="-1">运行环境：把一组运行安排放在一起 <a class="header-anchor" href="#运行环境-把一组运行安排放在一起" aria-label="Permalink to &quot;运行环境：把一组运行安排放在一起&quot;">​</a></h2><p>在平台的“运维管理”中，运行环境用于组织节点、基础服务、工程部署与访问设置。名称可以帮助区分用途，例如测试或正式使用。</p><p>“新建运行环境”创建的是平台中的运行范围，不会自动购买云服务器、安装新电脑或给所有服务分配无限资源。</p><p>这里的运行环境，也不是你正在使用的云开发工作区、操作系统版本或网页浏览器。</p><h2 id="节点-真实服务器的登记对象" tabindex="-1">节点：真实服务器的登记对象 <a class="header-anchor" href="#节点-真实服务器的登记对象" aria-label="Permalink to &quot;节点：真实服务器的登记对象&quot;">​</a></h2><p>节点通常是一台物理服务器或虚拟机。接入平台后，可以查看它的地址、心跳、CPU、内存、磁盘和相应资格。</p><p>节点能做什么，取决于实际类型、平台、驱动能力、运行资格和资源条件。不能只因显示在线，就判断它可以承载所有工程或协议。</p><p>你的笔记本能登录平台，不表示它自动成为节点；PLC 等现场设备是可能被节点访问的数据来源，也不等于已经登记的运行节点。</p><h2 id="基础服务和运行引擎做什么" tabindex="-1">基础服务和运行引擎做什么 <a class="header-anchor" href="#基础服务和运行引擎做什么" aria-label="Permalink to &quot;基础服务和运行引擎做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名词</th><th>可以怎样理解</th></tr></thead><tbody><tr><td>基础服务</td><td>环境中为工程提供存储、消息、对象文件或访问入口等能力的公共设施</td></tr><tr><td>运行引擎</td><td>在运行中执行工程数据访问、计算、报警等工作的服务程序</td></tr><tr><td>部署</td><td>选择工程内容、环境、节点和访问方式，形成一次实际运行安排</td></tr><tr><td>环境入口</td><td>环境中供应用使用的统一访问地址，不是平台管理员登录地址</td></tr></tbody></table><p>这些是不同对象。服务器接入成功，不代表基础服务已健康；基础服务就绪，也不代表工程已经部署。</p><h2 id="用一个应用看分工" tabindex="-1">用一个应用看分工 <a class="header-anchor" href="#用一个应用看分工" aria-label="Permalink to &quot;用一个应用看分工&quot;">​</a></h2><p>例如“温度监测工程”已经准备了一个正式版本：</p><ul><li>工程与版本确定<strong>要运行什么内容</strong>。</li><li>选择运行环境，确定<strong>在哪个范围中运行</strong>。</li><li>按实际条件选择节点，确定<strong>由哪些服务器承担任务</strong>。</li><li>创建部署，并检查服务、入口和业务结果，确认<strong>是否真的能使用</strong>。</li></ul><p>这是概念说明，不是一套已经验证的部署拓扑。实际跨节点放置和服务组合，应采用交付已确认的范围。</p><h2 id="开发环境和运行环境不同" tabindex="-1">开发环境和运行环境不同 <a class="header-anchor" href="#开发环境和运行环境不同" aria-label="Permalink to &quot;开发环境和运行环境不同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比</th><th>开发环境</th><th>运行环境</th></tr></thead><tbody><tr><td>主要用途</td><td>编写源码、配置和检查效果</td><td>承载选定内容的实际运行</td></tr><tr><td>常见入口</td><td>应用开发中的 AI、编辑器和页面预览</td><td>运维管理中的环境、节点、工程部署</td></tr><tr><td>内容变化</td><td>正在修改的开发内容</td><td>实际部署采用的工程版本或开发快照</td></tr><tr><td>结束开发</td><td>可以保存后停止开发工具</td><td>不因此自动停止或更新已部署应用</td></tr></tbody></table><p>“开发模式部署”也会形成实际运行快照，不等于浏览器里的实时预览；保存新源码不会自动更新这个快照。</p><h2 id="多节点不等于高可用" tabindex="-1">多节点不等于高可用 <a class="header-anchor" href="#多节点不等于高可用" aria-label="Permalink to &quot;多节点不等于高可用&quot;">​</a></h2><p>多个节点表示有多台服务器可以按条件参与工作。是否能自动切换、容忍某个服务故障或保护数据，还取决于实际服务部署和已验证能力。</p><p>当前基础服务界面里的主备、集群等未开放选项，不能因出现名称就当成可用功能。多存一份数据也不能自动代替备份。</p><p>不要为了调整环境直接删除节点、环境或基础服务：取消关联、移除登记、卸载程序和删除数据的影响不同。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>按任务查看<a href="/induframe-docs/zh/guide/runtime-environments.html">运行环境管理</a>、<a href="/induframe-docs/zh/guide/runtime-nodes.html">节点管理</a>、<a href="/induframe-docs/zh/guide/deployments.html">工程部署</a>和<a href="/induframe-docs/zh/guide/environment-entry.html">环境访问入口</a>。其他词可在<a href="/induframe-docs/zh/reference/glossary.html">常用术语解释</a>中查找。</p>',26)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
